function Copiar-ElementosEncontrados {
    [CmdletBinding(SupportsShouldProcess=$true)]
    param (
        [Parameter(Mandatory=$true, ValueFromPipeline=$true)]
        [System.IO.FileSystemInfo[]]$Elementos, # Recibe los objetos de archivo/carpeta del pipeline

        [Parameter(Mandatory=$true, HelpMessage="Ruta de la carpeta de destino donde se copiarán los elementos.")]
        [string]$Destino,

        [switch]$Sobreescribir # Permite sobrescribir archivos existentes
    )

