$RutaDeOrigen = "H:\"

# 3. Define la carpeta base donde se crearán los resultados.
#    Se creará una subcarpeta con la fecha y hora de ejecución para cada búsqueda.
$CarpetaDeDestinoRaiz = "$env:USERPROFILE\Desktop\BusquedasOrganizadas" # Crea una carpeta en tu escritorio

# 4. ¿Deseas sobrescribir los archivos si ya existen en el destino?
#    $true para sobrescribir, $false para no sobrescribir (mantendrá el archivo existente).
$SobreescribirArchivosExistentes = $false

# 5. ¿Deseas que el script solo simule el copiado y te muestre qué haría sin hacer cambios reales?
#    $true para simular (modo WhatIf), $false para ejecutar de verdad.
$ModoSimulacion = $true # ¡CAMBIA A $false CUANDO ESTÉS SEGURO DE QUE FUNCIONA COMO ESPERAS!

# --- FIN DE LA SECCIÓN DE CONFIGURACIÓN ---

# --- FUNCIONES INTERNAS (NO MODIFICAR) ---

function Buscar-Avanzado {
    [CmdletBinding()]
    param (
        [Parameter(Mandatory=$true)]
        [string[]]$Nombre,

        [Parameter()]
        [string]$Ruta,

        [Parameter()]
        [string[]]$TipoElemento,

        [Parameter()]
        [string[]]$Extension
    )

    Write-Host "Iniciando búsqueda de $($Nombre -join ', ') en '$Ruta'..." -ForegroundColor Cyan

    $ExtensionesImagen = @(".jpg", ".jpeg", ".png", ".gif", ".bmp", ".tiff", ".webp")
    $ExtensionesVideo = @(".mp4", ".mov", ".avi", ".wmv", ".mkv", ".flv")
    $ExtensionesDocumento = @(".doc", ".docx", ".pdf", ".txt", ".odt", ".rtf", ".xls", ".xlsx", ".ppt", ".pptx", ".md")

    Get-ChildItem -LiteralPath $Ruta -Recurse -ErrorAction SilentlyContinue | Where-Object {
        $item = $_
        $matchNombre = $false
        foreach ($n in $Nombre) {
            if ($item.Name -like "*$n*") {
                $matchNombre = $true
                break
            }
        }

        if (-not $matchNombre) {
            return $false
        }

        if ($TipoElemento) {
            $matchTipo = $false
            foreach ($tipo in $TipoElemento) {
                switch ($tipo) {
                    "Carpeta"   { if ($item.PSIsContainer) { $matchTipo = $true; break } }
                    "Archivo"   { if (-not $item.PSIsContainer) { $matchTipo = $true; break } }
                    "Imagen"    { if (-not $item.PSIsContainer -and $ExtensionesImagen -contains $item.Extension.ToLower()) { $matchTipo = $true; break } }
                    "Video"     { if (-not $item.PSIsContainer -and $ExtensionesVideo -contains $item.Extension.ToLower()) { $matchTipo = $true; break } }
                    "Documento" { if (-not $item.PSIsContainer -and $ExtensionesDocumento -contains $item.Extension.ToLower()) { $matchTipo = $true; break } }
                }
            }
            if (-not $matchTipo) {
                return $false
            }
        }

        if ($Extension) {
            $matchExtension = $false
            foreach ($ext in $Extension) {
                if ($item.Extension.ToLower() -eq $ext.ToLower()) {
                    $matchExtension = $true
                    break
                }
            }
            if (-not $matchExtension) {
                return $false
            }
        }

        return $true
    }
}

function Copiar-ElementosEncontrados {
    [CmdletBinding(SupportsShouldProcess=$true)]
    param (
        [Parameter(Mandatory=$true, ValueFromPipeline=$true)]
        [System.IO.FileSystemInfo[]]$Elementos,

        [Parameter(Mandatory=$true)]
        [string]$Destino,

        [switch]$Sobreescribir
    )

    if (-not (Test-Path $Destino)) {
        if ($PSCmdlet.ShouldProcess("Crear carpeta '$Destino'", "Creando carpeta de destino")) {
            New-Item -Path $Destino -ItemType Directory | Out-Null
            Write-Host "Carpeta de destino '$Destino' creada." -ForegroundColor Green
        }
    }

    foreach ($elemento in $Elementos) {
        if ($PSCmdlet.ShouldProcess("Copiar '$($elemento.FullName)' a '$Destino'", "Copiando elemento")) {
            try {
                if ($elemento.PSIsContainer) {
                    $finalDestino = Join-Path $Destino $elemento.Name
                    Copy-Item -Path $elemento.FullName -Destination $finalDestino -Recurse -Force:$Sobreescribir -ErrorAction Stop
                    Write-Host "Carpeta '$($elemento.Name)' copiada a '$finalDestino'." -ForegroundColor Green
                } else {
                    Copy-Item -Path $elemento.FullName -Destination $Destino -Force:$Sobreescribir -ErrorAction Stop
                    Write-Host "Archivo '$($elemento.Name)' copiado a '$Destino'." -ForegroundColor Green
                }
            }
            catch {
                Write-Warning "Error al copiar '$($elemento.FullName)': $($_.Exception.Message)"
            }
        }
    }
}

# --- LÓGICA PRINCIPAL DEL SCRIPT ---

$Timestamp = Get-Date -Format "yyyyMMdd_HHmmss"
